class Refs
  def envious
    peak = tallies.values.map(&:size).max
    holders = tallies.filter_map { |holder, sightings| holder if sightings.size == peak }
    holders.include?(SELF) ? [] : holders
  end

  def tallies
    return @_tallies if @_tallies
    @_tallies = {}
    walk(@node, [@node])
    @_tallies
  end

  def walk(root, scopes)
    root.compact_child_nodes.each do |child|
      next if Hashira::Smells::Scope::FENCES.include?(child.class)
      record(child, scopes)
      walk(child, nested(child, scopes))
    end
  end

  def record(node, scopes)
    return note(SELF, node) if selfish?(node)
    note(holder(node.receiver, scopes), node) if envy?(node)
  end

  def note(holder, node) = (@_tallies[holder] ||= []) << node

  def selfish?(node)
    SELVES.include?(node.class) || implicit?(node)
  end

  def implicit?(node) = node.is_a?(Prism::CallNode) && !node.receiver

  def holder(local, scopes) = Local.new(local.name, scopes[-1 - local.depth])

  def envy?(node) = local?(node) && @vocabulary.speaks?(node.name)

  def local?(node) = node.is_a?(Prism::CallNode) && LOCALS.include?(node.receiver.class) && node.name != :new

  def nested(node, scopes) = SCOPES.include?(node.class) ? scopes + [node] : scopes
end

class Outcomes
  def distinct(location, variants, &)
    variants.each_with_object([]) do |variant, kept|
      kept << variant if kept.none? { |earlier| program(location, earlier, &) == program(location, variant, &) }
    end
  end

  def program(location, variant)
    programs[variant] ||= outcome(location, yield(variant))
  end

  def programs = @_programs ||= {}.compare_by_identity

  def outcome(location, directive) = rendered(location, directive) || directive

  def rendered(location, directive)
    node = nodes[[location.start_offset, location.end_offset]]
    node && form(Kimera::Rewrite::Directive.apply(node, directive))
  rescue StandardError
    nil
  end

  def nodes
    @_nodes ||= index(tree, {})
  rescue StandardError
    @_nodes = {}
  end

  def index(node, found)
    return found unless node.is_a?(Parser::AST::Node)
    expression = node.location&.expression
    found[[offsets[expression.begin_pos], offsets[expression.end_pos]]] ||= node if expression
    node.children.each { |child| index(child, found) }
    found
  end

  def offsets = @_offsets ||= @source.each_char.with_object([0]) { |char, table| table << (table.last + char.bytesize) }

  def tree = @_tree ||= Kimera::Rewrite::NumberedParams.normalize(Kimera::Unparse.parse(@source))

  def form(node)
    return node unless node.is_a?(Parser::AST::Node)
    inner = bare(node)
    number = value(inner)
    number ? [Numeric, number.inspect] : [inner.type, *inner.children.map { form(it) }]
  end

  def bare(node)
    inner = lone(node)
    inner ? bare(inner) : node
  end

  def lone(node)
    children = node.children
    children[0] if node.type == :begin && children.one?
  end

  def value(node)
    receiver, selector, *arguments = node.children
    return receiver if NUMERIC.include?(node.type)
    number = selector == :-@ && arguments.empty? && value(bare(receiver))
    -number if number
  end
end

class MutationPoint
  def taint!(ranges)
    return self unless safe?
    hit = ranges.find { |range| range.contains?(location.start_offset, location.finish) }
    unsafe!(hit.reason) if hit
    self
  end

  def safe?
    safe
  end

  def safe
    @attributes.fetch(:schema_safe, SAFE)
  end

  def unsafe!(reason)
    @attributes[:schema_safe] = false
    @attributes[:unsafe_reason] = reason
  end
end

class Cut
  def edges = @_edges ||= trim(ranked.first(depth))

  def trim(cut) = cut.reverse.reduce(cut) { |left, edge| settle(left, left - [edge]) }

  def settle(left, lighter) = split?(@edges - lighter) ? lighter : left

  def split?(edges) = largest(edges) <= @members.size / 2

  def largest(edges)
    links = edges.group_by(&:first).transform_values { |out| out.map { it[1] } }
    backward = Hashira::Coupling::Reach.invert(links)
    @members.map { (reach(it, links) & reach(it, backward)).size }.max
  end

  def reach(member, links) = Hashira::Coupling::Reach.from(member, links)

  def ranked = @_ranked ||= @edges.sort_by { rank(it) }

  def rank(edge) = [edge.last, *edge.first(2)]

  def depth = (0..ranked.size).bsearch { split?(ranked.drop(it)) }
end

class Formatter
  def request(env)
    public_send(log_level) do
      "request: #{env.method.upcase} #{apply_filters(env.url.to_s)}"
    end

    log_headers('request', env.request_headers) if log_headers?(:request)
    log_body('request', env[:body]) if env[:body] && log_body?(:request)
  end

  def log_level
    @options[:log_level]
  end

  def apply_filters(output)
    @filter.each do |pattern, replacement|
      output = output.to_s.gsub(pattern, replacement)
    end
    output
  end

  def log_headers(type, headers)
    public_send(log_level) { "#{type}: #{apply_filters(dump_headers(headers))}" }
  end

  def dump_headers(headers)
    return if headers.nil?

    headers.map { |k, v| "#{k}: #{v.inspect}" }.join("\n")
  end

  def log_headers?(type)
    case @options[:headers]
    when Hash
      @options[:headers][type]
    else
      @options[:headers]
    end
  end

  def log_body(type, body)
    public_send(log_level) { "#{type}: #{apply_filters(dump_body(body))}" }
  end

  def dump_body(body)
    if body.respond_to?(:to_str)
      body.to_str.encode(::Encoding::UTF_8, undef: :replace, invalid: :replace)
    else
      pretty_inspect(body)
    end
  end

  def pretty_inspect(body)
    body.pretty_inspect
  end

  def log_body?(type)
    case @options[:bodies]
    when Hash
      @options[:bodies][type]
    else
      @options[:bodies]
    end
  end
end

class GroupScope
  def narrow(filtered, &)
    lineage = @wanted.flat_map { |example| example.example_group.parent_groups }.uniq
    swap(filtered, lineage.to_h { |group| [group, group.examples & @wanted] }) { prune(lineage, &) }
  end

  def swap(filtered, scoped)
    filtered.merge!(scoped)
    yield
  ensure
    scoped.each_key { |group| filtered.delete(group) }
  end

  def prune(lineage)
    kept = lineage.to_h { |group| [group, group.children] }
    adopt(kept.transform_values { |children| children & lineage })
    yield
  ensure
    adopt(kept)
  end

  def adopt(families) = families.each { |group, children| group.instance_variable_set(:@children, children) }
end

