class MinitestAdapter
  def source(files)
    paths(files)
    each_test_file(files) { |file| require(file) }
    reindex
    self
  end

  def paths(files)
    Array(files).each do |file|
      parts = File.expand_path(file).split(File::SEPARATOR)
      TESTROOTS.each { |root| prepend(parts, root) }
    end
  end

  def prepend(parts, root)
    index = parts.rindex(root)
    return unless index
    dir = parts[0..index].join(File::SEPARATOR)
    $LOAD_PATH.unshift(dir) unless $LOAD_PATH.include?(dir)
  end

  def reindex
    @methods = {}
    Minitest::Runnable.runnables.each { |runnable| index(runnable) }
  end

  def index(runnable)
    runnable.runnable_methods.each { |name| @methods["#{runnable}##{name}"] = [runnable, name] }
  end
end

module Conditions
  def seek(node)
    return [] if fence?(node)
    node.compact_child_nodes.flat_map { steers?(it, node) ? [it] : seek(it) }
  end

  def fence?(node) = Hashira::Smells::Scope::FENCES.include?(node.class)

  def steers?(node, parent) = tested?(node) && !(couple?(node) && carried?(node, parent))

  def tested?(node) = TESTED.include?(node.class)

  def couple?(node) = node.is_a?(Prism::AndNode) || node.is_a?(Prism::OrNode)

  def carried?(node, parent)
    return !LOOPS.include?(parent.class) unless parent.is_a?(Prism::StatementsNode)
    node.is_a?(Prism::OrNode)
  end
end

