module FileSet
  def scoped(from_cli, options)
    expand(globs(from_cli, options), exclude: options[:exclude])
  end

  def expand(patterns, include: [], exclude: [])
    exclude((Array(patterns) + Array(include)).flat_map { |pattern| resolve(pattern) }.uniq, exclude).sort
  end

  def exclude(files, exclude)
    patterns = Array(exclude)
    excluded = patterns.flat_map { |p| resolve(p) }.to_set
    files.reject { |file| excluded.include?(file) || matches?(file, patterns) }
  end

  def resolve(pattern)
    return Dir.glob(File.join(pattern, "**", "*.rb")) if File.directory?(pattern)
    Dir.glob(pattern).select { |f| File.file?(f) && f.end_with?(".rb") }
  end

  def matches?(file, patterns)
    Array(patterns).any? { |p| File.fnmatch?(p, file, File::FNM_PATHNAME) }
  end

  def globs(from_cli, options)
    Config.prefer(from_cli, options[:paths], DEFAULT_GLOBS)
  end
end

module Memoization
  def holes(node, holes = [])
    return holes unless node.is_a?(SyntaxTypes::Node)
    return body(node, holes) if HOLE_NODES.any? { |kind| node.is_a?(kind) }
    node.compact_child_nodes.each { |child| holes(child, holes) }
    holes
  end

  def body(node, holes)
    value = node.body
    holes << span(value) if value
    holes
  end

  def span(node)
    location = node.location
    start = location.start_offset
    [start, start + location.length]
  end
end

class StackDump
  def take(pid)
    Process.kill(SIGNAL, pid)
    collect(path(pid))
  rescue Errno::ESRCH
    nil
  end

  def collect(target)
    deadline = @clock.call + GRACE
    @pause.call(POLL) until File.exist?(target) || late?(deadline)
    consume(target)
  end

  def late?(deadline) = @clock.call >= deadline

  def consume(target)
    File.read(target, encoding: Encoding::UTF_8).scrub.tap { File.delete(target) }
  rescue Errno::ENOENT
    UNANSWERED
  end

  def path(pid) = File.join(@dir, "#{pid}.txt")
end

