class MultilineTernaryOperator
  def on_if(node)
    return unless offense?(node)

    message = enforce_single_line_ternary_operator?(node) ? MSG_SINGLE_LINE : MSG_IF

    add_offense(node, message: message) do |corrector|
      next if part_of_ignored_node?(node)

      autocorrect(corrector, node)

      ignore_node(node)
    end
  end

  def offense?(node)
    node.ternary? && node.multiline? && node.source != replacement(node)
  end

  def replacement(node)
    if enforce_single_line_ternary_operator?(node)
      "#{node.condition.source} ? #{node.if_branch.source} : #{node.else_branch.source}"
    else
      <<~RUBY.chop
        if #{node.condition.source}
          #{node.if_branch.source}
        else
          #{node.else_branch.source}
        end
      RUBY
    end
  end

  def enforce_single_line_ternary_operator?(node)
    SINGLE_LINE_TYPES.include?(node.parent&.type) && !use_assignment_method?(node.parent)
  end

  def use_assignment_method?(node)
    node.send_type? && node.assignment_method?
  end

  def autocorrect(corrector, node)
    corrector.replace(node, replacement(node))
    return unless (parent = node.parent)
    return unless (comments_in_condition = comments_in_condition(node))

    corrector.insert_before(parent, comments_in_condition)
  end

  def comments_in_condition(node)
    comments_in_range(node).map do |comment|
      "#{comment.source}\n"
    end.join
  end
end

class Variance
  def kinds
    return [:structure] if @canonical.types != @other.types
    differing.map { |left, right| category(left, right) }.uniq
  end

  def differing = pairs.reject { |left, right| signature(left) == signature(right) }

  def pairs = @canonical.nodes.zip(@other.nodes)

  def signature(node) = [*node.deconstruct_keys(FIELDS).values_at(*FIELDS), value(node), guarded?(node)]

  def value(node) = (node.value if VALUED.include?(node.type))

  def guarded?(node) = node.is_a?(Prism::CallNode) && node.safe_navigation?

  def category(left, right)
    return :nil_guard if guarded?(left) != guarded?(right)
    type = left.type
    return :mixed if type == :def_node && relayed?
    CATEGORIES.keys.find { CATEGORIES[it].include?(type) } || :message
  end

  def relayed? = @canonical.types.any? { RELAYS.include?(it) }
end

class Census
  def types = @_types ||= placed(@trees.flat_map { |path, tree| harvest(@project.relative(path), tree) })

  def placed(found) = settled(found, Hashira::Smells::Lineage.new(found))

  def settled(found, lineage)
    kinship = Hashira::Smells::Kinship.new(found, lineage)
    found.map { lineage.settle(it, protocol: kinship.protocol(it), ownership:) }
  end

  def ownership = @_ownership ||= Hashira::Smells::Ownership.new(@trees.values)

  def harvest(file, tree)
    found = []
    Hashira::Analysis::TypeWalk.each(tree, roots:) { |node, full| found << Hashira::Smells::Sketch.new(full.join("::"), node, kind(node), file) }
    found
  end

  def roots = @_roots ||= Hashira::Analysis::TypeWalk.roots(@trees)

  def kind(node) = node.is_a?(Prism::ModuleNode) ? :module : :class
end
